import{_ as n}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as s,D as c,o as l,c as _,I as d,w as h,k as r,a as u,R as m,b as p,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const I=JSON.parse('{"title":"设计原则、常见模式与综合复习","description":"用 SOLID 和常见设计模式完成综合项目，并按路线复盘 Java 全部核心知识。","frontmatter":{"title":"设计原则、常见模式与综合复习","date":"2026-09-22T00:00:00.000Z","category":"Java系统补习","tags":["Java","设计原则","设计模式","综合项目"],"description":"用 SOLID 和常见设计模式完成综合项目，并按路线复盘 Java 全部核心知识。"},"headers":[],"relativePath":"courses/java/12-设计与项目/01-设计原则模式与综合复习.md","filePath":"courses/java/12-设计与项目/01-设计原则模式与综合复习.md","lastUpdated":1790079096000}'),J={name:"courses/java/12-设计与项目/01-设计原则模式与综合复习.md"},b=r("h1",{id:"设计原则、常见模式与综合复习",tabindex:"-1"},[u("设计原则、常见模式与综合复习 "),r("a",{class:"header-anchor",href:"#设计原则、常见模式与综合复习","aria-label":'Permalink to "设计原则、常见模式与综合复习"'},"​")],-1),v=m('<h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>用单一职责、开闭、里氏替换、接口隔离、依赖倒置审查设计。</li><li>识别策略、工厂、建造者、装饰器、观察者、模板方法和适配器模式。</li><li>把语言、集合、并发、JVM、测试和数据库知识整合到一个项目。</li><li>建立从需求、实现、测试、观测、性能到复盘的进阶学习路线。</li></ul><h2 id="核心知识点" tabindex="-1">核心知识点 <a class="header-anchor" href="#核心知识点" aria-label="Permalink to &quot;核心知识点&quot;">​</a></h2><p>模式是重复出现的协作结构，不是类名清单；先识别变化点和约束，再选择策略或工厂等模式。综合项目可做“订单/库存服务”：用 record 表示命令和结果，用接口隔离支付策略，用集合维护内存索引，用 Stream 生成报表，用 JDBC 持久化，用 Maven/JUnit/日志形成工程闭环，用 Executor 或虚拟线程处理异步任务，再通过 JFR 和 GC 日志验证性能。复习顺序建议为：语法与对象 → 异常/泛型/集合 → Lambda/Stream/IO → 反射/模块 → 并发/JMM → JVM → 工程化；每阶段都要完成一个可运行练习并写测试。</p><h2 id="实践任务" tabindex="-1">实践任务 <a class="header-anchor" href="#实践任务" aria-label="Permalink to &quot;实践任务&quot;">​</a></h2><p>分四轮完成订单项目：第一轮命令行内存版，第二轮加入 Maven、JUnit 和日志，第三轮接入 JDBC 与事务，第四轮加入并发下单、超时、指标和 JVM 压测。每轮记录设计决策、失败用例、性能基线和下一步改进。</p><h2 id="易错点" tabindex="-1">易错点 <a class="header-anchor" href="#易错点" aria-label="Permalink to &quot;易错点&quot;">​</a></h2><ul><li>为了套模式而套模式，抽象层级超过真实变化点。</li><li>只测 happy path，不测重试、并发、超时、回滚和资源关闭。</li><li>把“能运行”当作“可维护”，没有边界、日志、指标和文档。</li><li>只背 JVM 参数或 API，不用可复现实验验证假设。</li></ul><h2 id="复习清单" tabindex="-1">复习清单 <a class="header-anchor" href="#复习清单" aria-label="Permalink to &quot;复习清单&quot;">​</a></h2><ul><li>[ ] 能用 SOLID 解释一次重构前后的取舍。</li><li>[ ] 能为综合项目画模块、线程、事务和数据流边界。</li><li>[ ] 能从日志、测试、线程转储、GC 日志和指标定位问题。</li><li>[ ] 能按“读概念—写最小例子—做故障实验—总结决策”循环继续进阶。</li></ul>',10);function k(a,C,P,V,q,M){const i=n,o=c("ClientOnly");return l(),_("div",null,[b,d(o,null,{default:h(()=>{var e,t;return[(((e=a.$frontmatter)==null?void 0:e.aside)??!0)&&(((t=a.$frontmatter)==null?void 0:t.showArticleMetadata)??!0)?(l(),p(i,{key:0,article:a.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),v])}const T=s(J,[["render",k]]);export{I as __pageData,T as default};
